import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"1、【乾】 乾下乾上","description":"周易集注 - 1、【乾】 乾下乾上","frontmatter":{"title":"1、【乾】 乾下乾上","description":"周易集注 - 1、【乾】 乾下乾上"},"headers":[],"relativePath":"zh/classics/jizhu/005.md","filePath":"zh/classics/jizhu/005.md"}'),l={name:"zh/classics/jizhu/005.md"};function p(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_1、【乾】-乾下乾上" tabindex="-1">1、【乾】 乾下乾上 <a class="header-anchor" href="#_1、【乾】-乾下乾上" aria-label="Permalink to “1、【乾】 乾下乾上”">​</a></h1><p>乾，卦名。元亨利贞者，文王所系之辞，以断一卦之吉凶，所谓彖辞也。乾者健也，阳主于动，动而有常，其动不息，非至健不能。奇者阳之数，天者阳之体，健者阳之性，如火性热水性寒也。六画皆奇，则纯阳而至健矣，故不言天而言干也。元大，亨通，利宜，贞正而固也。元亨者，天道之本然，数也。利贞者，人事之当然，理也。易经理数不相离，因乾道阳明纯粹，无纤毫阴柔之私，惟天与圣人足以当之，所以断其必大亨也。故数当大亨而必以贞处之，方与乾道相合。若其不贞，少有人欲之私，则人事之当然者废，又安能元亨乎。故文王言，筮得此卦者大亨而宜于正固，此则圣人作易，开物成务，冒天下之道，教人以反身修省之切要也。学者能于此四字潜心焉，传心之要不外是矣。此文王占卜所系之辞，不可即指为四德。至孔子文言，纯以义理论，方指为四德也。盖占卜，不论天子，不论庶人，皆宜于贞，若即以为四德，失文王立教之意矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><h3 id="大哉乾元-万物资始-乃统天。" tabindex="-1">大哉乾元，万物资始，乃统天。 <a class="header-anchor" href="#大哉乾元-万物资始-乃统天。" aria-label="Permalink to “大哉乾元，万物资始，乃统天。”">​</a></h3><p>乾元亨利贞者，文王所系之辞，彖之经也。此则孔子赞经之辞，彖之传也。故亦以彖曰起之。彖者材也，言一卦之材也。后人解彖者断也，又解豕走悦，又解为茅犀之名，不如只依孔子材之一字可也。下文象曰象字亦然。易本占卜之书，曰元亨利贞者，文王主于卜筮以教人。至于孔子之传，则专于义理矣，故以元亨利贞，分为四德，此则专以天道发明干义也。大哉，叹辞。乾元者，干之元也。元者大也，始也。始者，物之始，非以万物之始即元也。言万物所资以始者，此乃四德之元也。此言气而不言形，若涉于形，便是坤之资生矣。统，包括也，乾元乃天德之大始，故万物之生，皆资之以为始。又为四德之首，而贯乎天德之始终，故统天。天之为天，出乎震，而生长收藏，不过此四德而己，统四德则统天矣。资始者，无物不有也。统天者，无时不然也。无物不有，无时不然，此乾元之所以为大也。此释元之义。</p><h3 id="云行雨施-品物流形。" tabindex="-1">云行雨施，品物流形。 <a class="header-anchor" href="#云行雨施-品物流形。" aria-label="Permalink to “云行雨施，品物流形。”">​</a></h3><p>有是气即有是形。资始者气也，气发泄之盛，则云行雨施矣。品者，物各分类。流者，物各以类而生生不已，其机不停滞也。云行雨施者气之亨，品物流形者物随造化以亨也。虽物之亨通，而其实乾德之亨通也。此释干之亨。施有二义，平声者用也加也设也，去声者布也散也惠也与也。此则去声之义。</p><h3 id="大明终始-六位时成-时乘六龙以御天。" tabindex="-1">大明终始，六位时成，时乘六龙以御天。 <a class="header-anchor" href="#大明终始-六位时成-时乘六龙以御天。" aria-label="Permalink to “大明终始，六位时成，时乘六龙以御天。”">​</a></h3><p>大明者，默契也。终谓上爻，始谓初爻。即初辞拟之，卒成之终，原始要终以为质也。观下句六位二字可见矣。六位者六爻也，时者六爻相杂，惟其时物之时也。爻有定位，故曰六位。六龙者，潜与亢之六龙六阳也。阳有变化，故曰六龙。乘者凭据也，御者御车之御，犹运用也。上文言统者，统治纲领，统天之统如身之统四体。此节言御者，分治条目。御天之御，如心之御五官。六位时成者，如位在初时当为潜，位在上时当为亢也。御天者，行天道也。当处之时则乘潜龙，当出之时则乘飞龙，时当勿用圣人则勿用，时当知悔圣人则知悔也。乘龙御天，只是时中。乘六龙便是御天，谓之曰乘龙御天，则是圣人一身常驾驭乎干之六龙，而干之六龙常在圣人运用之中矣。学者当观其时成时乘，圣人时中变化，行无辙迹之妙可也。然言天道而配以圣人何也?盖天下之理得而成位乎中，则参天地者惟圣人也，故颐卦曰圣人养贤以及万民，咸卦曰圣人感人心而天下和平，恒卦曰圣人久于其道而天下化成，皆此意。</p><p>言圣人默契乾道六爻终始之理，见六爻之位各有攸当，皆以时自然而成，则六阳浅深进退之时，皆在吾运用之中矣。由是时乘六龙，以行天道，则圣即天也。上一节专赞乾元，此一节则赞圣人，知干六爻之理而行乾元之事。则泽及于物，足以为万国咸宁之基本矣，乃圣人之元亨也。</p><h3 id="乾道变化-各正性命-保合太和-乃利贞。" tabindex="-1">乾道变化，各正性命，保合太和，乃利贞。 <a class="header-anchor" href="#乾道变化-各正性命-保合太和-乃利贞。" aria-label="Permalink to “乾道变化，各正性命，保合太和，乃利贞。”">​</a></h3><p>变者化之渐，化者变之成。各者各自也，即一物原来有一身，各有族类，不混淆也。正者不偏也，言万物受质，各得其宜，即一身还有一乾坤，不得倚附妨害也。物所受为性，天所赋为命，保者常存而不亏，合者翕聚而不散。太和，阴阳会合，冲和之气也。各正者，各正于万物向实之初。保合者，保合于万物向实之后。就各正言，则曰性命，性命虽以理言而不离乎气。就保合言，则曰太和，虽以气言，而不离乎理，其实非有二也。</p><p>言乾道变化不穷，固品物流形矣。至秋则物皆向实，各正其所受所赋之性命，至冬则保全其太和生意，随在饱足，无少缺欠。凡资始于元，流形于亨者，至此告其终，敛其迹矣，虽万物之利贞，实乾道之利贞也，故曰乃利贞。</p><h3 id="首出庶物-万国咸宁。" tabindex="-1">首出庶物，万国咸宁。 <a class="header-anchor" href="#首出庶物-万国咸宁。" aria-label="Permalink to “首出庶物，万国咸宁。”">​</a></h3><p>乘龙御天，乃圣人王道之始，为天下开太平，至此则惟端拱首出于万民之上。如乾道变化，无所作为，而万国咸宁，亦如物之各正保合也。乘龙御天之化至此，成其功矣，此则圣人之利贞也。咸宁之宁，即各正保合也，其文武成康之时乎，汉文帝亦近之。如不能各正保合，则纷纭烦扰矣，岂得宁。</p><p>《象》曰：天行健，君子以自彊不息。</p><p>象者，伏羲卦之上下两象，周公六爻所系辞之象也，即彖辞之下，即以彖曰起之是也。天行者，天之运行，一日一周也。健者运而不息也，其不息者，以阳之性至健，所以不息也。以者用也，有所因而用之，之辞即箕子以之之以也。体易而用之，乃孔子示万世学者用易之方也。自彊者，一念一事，莫非天德之刚也。息者，间以人欲也。天理周流，人欲退听，故自彊不息，若少有一毫阴柔之私以间之，则息矣。彊与息反，如公与私反。自彊不息，犹云至公无私。天行健者，在天之干也。自彊不息者，在我之干也。上句以卦言，下句以人事言，诸卦仿此。</p><p>初九，潜龙勿用。</p><p>此周公所系之辞，以断一爻之吉凶，所谓爻辞也。凡画卦者，自下而上，故谓下爻为初。初九者，卦下阳爻之名也。阳曰九，阴曰六者，河图洛书，五皆居中，则五者数之祖也，故圣人起数，止于一二三四五。参天两地而倚数，参天者，天之位三，天一天三天五也。两地者，地之二位也，地二地四也。倚者依也，天一依天三，天三依天五而为九，所以阳皆言九。地二依地四而为六，所以阴皆言六。一二三四五者，生数也，六七八九十者，成数也。然生数者成之端倪，成数者生之结果，故止以生数起之。过揲之数，皆以此九六之参两，所以爻言九六也。潜藏也，象初。龙阳物，变化莫测，亦犹乾道变化，故象九。且此爻变巽错震，亦有龙象，故六爻即以龙言之，所谓拟诸形容象其物宜者此也。勿用者，未可施用也。象为潜龙，占为勿用，故占得干而遇此爻之变者，当观此象，而玩此占也。诸爻仿此。易不似别经，不可为典要，如占得潜龙之象，在天子则当传位，在公卿则当退休，在士子则当静修，在贤人则当隐逸，在商贾则当待价，在战阵则当左次，在女子则当愆期，万事万物莫不皆然。若不知象，一爻止一事，则三百八十四爻止作得三百八十四件事矣。何以弥纶天地?此训象训字训错综之义，圈外方是正意。三百八十四爻仿此。</p><p>初九阳气方萌，在于卦下，盖龙之潜藏而未出者也，故有潜龙之象。龙未出潜，则未可施用矣，故教占者勿用，养晦以俟时可也。</p><h3 id="象曰-潜龙勿用-阳在下也。" tabindex="-1">象曰：潜龙勿用，阳在下也。 <a class="header-anchor" href="#象曰-潜龙勿用-阳在下也。" aria-label="Permalink to “象曰：潜龙勿用，阳在下也。”">​</a></h3><p>阳在下者，阳爻居于下也。阳故称龙，在下，故勿用。此以下举周公所系六爻之辞而释之，干初曰阳在下，坤初曰阴始凝，扶阳抑阴之意见矣。</p><p>九二，见龙在田，利见大人。</p><p>二谓自下而上第二爻也。九二非正，然刚健中正，本干之德，故旧注亦以正言之。见者，初为潜，二则离潜而出见也。田者，地之有水者也，以六画卦言之，二于三才为地道，地上即田也。大人者，大德之人也，阳大阴小，乾卦六爻皆阳，故为大，以三画卦言之，二于三才为人道，大人之象也。故称大人，所以应爻九五亦曰大人。二五得称大人者，皆以三画卦言也。利见大人者，利见九五之君，以行其道也。如仕进则利见君，如杂占则即今占卜利见贵人之类。此爻变离，有同人象，故利见大人。</p><p>九二以阳刚中正之德，当出潜离隐之时，而上应九五之君，故有此象，而其占则利见大人也。占者有是德，方应是占矣。</p><h3 id="象曰-见龙在田-德施普也。" tabindex="-1">象曰：见龙在田，德施普也。 <a class="header-anchor" href="#象曰-见龙在田-德施普也。" aria-label="Permalink to “象曰：见龙在田，德施普也。”">​</a></h3><p>德，即刚健中正之德。出潜离隐，则君德已著，周遍于物，故曰德施普。施字如程传作去声。</p><p>九三，君子终日乾乾，夕惕若，厉，无咎。</p><p>君子指占者，以六画卦言之，三于三才为人道，以乾德而居人道，君子之象也，故三不言龙。三变则中爻为离，离日在下卦之中，终日之象也。下干终而上干继，乾乾之象，乃健而不息也。终日是昼，夕则将夜，惕忧也。变离错坎，忧之象也。若，助语辞。夕对终日言。终日乾乾夕惕若者，言终日乾乾，虽至于夕，而兢惕之心，犹夫终日也。厉者，危厉不安也。九阳爻，三阳位，过则不中，多凶之地也，故言厉。无咎者，以危道处危地，操心危虑患深，则终于不危矣，此不易之理也，故无咎。</p><p>九三过刚不中，若有咎矣。然性体刚健，有能朝夕兢惕不已之象，占者能忧惧如是，亦无咎也。</p><h3 id="象曰-终日乾乾-反复道也。" tabindex="-1">象曰：终日乾乾，反复道也。 <a class="header-anchor" href="#象曰-终日乾乾-反复道也。" aria-label="Permalink to “象曰：终日乾乾，反复道也。”">​</a></h3><p>反复犹往来，言君子之所以干夕兢惕，汲汲皇皇，往来而不已者，无非此道而已。动循天理，所以处危地而无咎。道外无德，故二爻言德。</p><p>九四，或跃在渊，无咎。</p><p>或者欲进未定之辞，非犹豫狐疑也。或跃在渊者，欲跃犹在渊也。九为阳，阳动故言跃。四为阴，阴虚故象渊。此爻变巽为进退，为不果。又四多惧，故或跃在渊。</p><p>九四以阳居阴，阳则志于进，阴则不果于进，居上之下，当改革之际，欲进未定之时也，故有或跃在渊之象。占者能随时进退，斯无咎矣。</p><h3 id="象曰-或跃在渊-进无咎也。" tabindex="-1">象曰：或跃在渊，进无咎也。 <a class="header-anchor" href="#象曰-或跃在渊-进无咎也。" aria-label="Permalink to “象曰：或跃在渊，进无咎也。”">​</a></h3><p>量可而进，适其时则无咎，故孔子加一进字以断之。</p><p>九五，飞龙在天，利见大人。</p><p>五，天位，龙飞于天之象也。占法与九二同者，二五皆中位，特分上下耳。利见大人，如尧之见舜，高宗之见傅说是也。下此如沛公之见张良，昭烈之见孔明，亦庶几近之。六画之卦，五为天，三画之卦，五为人，故曰天曰人。</p><p>九五刚健中正，以圣人之德，居天子之位，而下应九二，故其象占如此。占者如无九五之德位，必不应利见之占矣。</p><h3 id="象曰-飞龙在天-大人造也。" tabindex="-1">象曰：飞龙在天，大人造也。 <a class="header-anchor" href="#象曰-飞龙在天-大人造也。" aria-label="Permalink to “象曰：飞龙在天，大人造也。”">​</a></h3><p>造作也，言作而在上也，非制作之作。大人龙也，飞在天，作而在上也。大人，释龙字。造释飞字。此止言飞龙在天。下同声相应一节，则言利见大人。上治一节，方言大人之事。乃位乎天德一节，则见其非无德而据尊位，四意自别。</p><p>上九，亢龙有悔。</p><p>上者，最上一爻之名。亢，以户唐切，人颈也，以苦浪切，高也。吴幼清以人之喉骨刚而居高是也。盖上而不能下，信而不能屈之意。阴阳之理，极处必变，阳极则生阴，阴极则生阳，消长盈虚，此一定之理数也。龙之为物，始而潜，继而见，中而跃，终而飞，既飞于天，至秋分又蛰而潜于渊，此知进知退，变化莫测之物也。九五飞龙在天位之极，中正者，得时之极，乃在于此，若复过于此，则极而亢矣。以时则极，以势则穷，安得不悔。</p><p>上九阳刚之极，有亢龙之象，故占者有悔。知进知退，不与时偕极，斯无悔矣。伊尹之复政厥辟，周公之罔以宠利居成功，皆无悔者也。</p><h3 id="象曰-亢龙有悔-盈不可久也。" tabindex="-1">象曰：亢龙有悔，盈不可久也。 <a class="header-anchor" href="#象曰-亢龙有悔-盈不可久也。" aria-label="Permalink to “象曰：亢龙有悔，盈不可久也。”">​</a></h3><p>此阴阳盈虚一定之理，盈即亢，不可久，致悔之由。</p><p>用九，见群龙无首，吉。</p><p>此因上九亢龙有悔而言之。用九者，犹言处此上九之位也。上九贵而无位，高而无民，贤人在下位而无辅，动而有悔矣。到此何以处之哉?惟见群龙无首则吉。群龙者，潜见跃飞之龙也。首者头也，干为首。凡卦，初为足，上为首，则上九即群龙之首也。不见其首则阳变为阴，刚变为柔，知进知退，知存知亡，知得知丧，不为穷灾，不与时偕极，乃见天则而天下治矣，所以无悔而吉。此圣人开迁善之门，教占者用此道也。故阳极则教以见群龙无首吉，阴极则教以利永贞。盖居九而为九所用，我不能用九，故至于亢。居六而为六所用，我不能用六，故至于战。惟见群龙无首利永贞，此用九用六之道也。干主知，坤主能，故言利永贞。用易存乎人，故圣人教之以此。昔王介甫常欲系用九于亢龙有悔之下，得其旨矣。</p><h3 id="象曰-用九-天德不可为首也。" tabindex="-1">象曰：用九，天德不可为首也。 <a class="header-anchor" href="#象曰-用九-天德不可为首也。" aria-label="Permalink to “象曰：用九，天德不可为首也。”">​</a></h3><p>天德二字，即乾道二字。首头也，即见群龙无首之首也。言周公爻辞，用九见群龙无首吉者何也，以天德不可为首，而见其首也。盖阳刚之极，亢则有悔，故用其九者，刚而能柔，有群龙无首之象则吉矣。天行以下，先儒谓之大象，潜龙以下，先儒谓之小象，后仿此。</p><h2 id="文言" tabindex="-1">文言 <a class="header-anchor" href="#文言" aria-label="Permalink to “文言”">​</a></h2><h3 id="元者善之长也-亨者嘉之会也-利者义之和也-贞者事之干也。" tabindex="-1">元者善之长也，亨者嘉之会也，利者义之和也，贞者事之干也。 <a class="header-anchor" href="#元者善之长也-亨者嘉之会也-利者义之和也-贞者事之干也。" aria-label="Permalink to “元者善之长也，亨者嘉之会也，利者义之和也，贞者事之干也。”">​</a></h3><p>孔子于彖象既作之后，犹以为未尽其蕴也，故又设文言以明之。文言者，依文以言其理，亦有文之言辞也。乾道所包者广，有在天之元亨利贞，有圣人之元亨利贞，有在人所具之元亨利贞，此则就人所具而言也。元，大也，始也，即在人之仁也。仁义礼智皆善也，但仁则善端初发，义礼智皆所从出，故为善之长。亨者自理之显著亨通而言，即在人之礼也。嘉，美之会聚也。利有二义，以人心言之，义为天理，利为人欲，此以利欲而言也。以天理言之，义者利之理和者，义之宜以合宜而言也，故利即吾性之义，义安处即利也。如上下彼此，各得其当然之分，不相乖戾，此利也，乃义之和也。贞有三意，知也正也固也，如孟子所谓知斯二者弗去是也。知者，知之意也;惟知事亲从兄，正之意也;弗去，固之意也。故贞即吾性之智。干者茎干也，木之身也。其义意则能事也，如木之身而枝叶所依以立也。筑墙两旁木制板者为干，从木，此字则从干。元就其理之发端而言，亨就其理之聚会而言，利就其理之各归分愿而言，贞就其理之确实而言，名虽有四，其实一理而已，皆天下之至公，而无一毫人欲之私者也。此四句说天德之自然，下体仁四句，说人事之当然。</p><h3 id="君子体仁足以长人-嘉会足以合礼-利物足以和义-贞固足以干事。" tabindex="-1">君子体仁足以长人，嘉会足以合礼，利物足以和义，贞固足以干事。 <a class="header-anchor" href="#君子体仁足以长人-嘉会足以合礼-利物足以和义-贞固足以干事。" aria-label="Permalink to “君子体仁足以长人，嘉会足以合礼，利物足以和义，贞固足以干事。”">​</a></h3><p>体者，所存所发，无不在于仁也。能体其仁，则欲立欲达，无所往而莫非真爱，自足以长人矣。长者克君克长之长，盖仁者宜在高位也，既足以长人，则善之长在我矣。下三句仿此。嘉会者，嘉美其会，聚于一身也。礼之方行，升降上下，进退屈伸，辞让授受，往来酬酢，未有单行独坐而可以行礼者，此之谓会。然其聚会，必至善恰好，皆天理人情自然之至，而无不嘉美焉，此之谓嘉。嘉美会聚于一身，则动容周旋，无不中礼，自有以合乎天理之节文，人事之仪则矣。盖此理在日用间，随处充足，无少欠缺。礼仪三百，威仪三千，无一事而非仁，若少有一毫欠缺，非美会矣，安能合礼。不相妨害之谓利，利则必和无所乖戾之谓和，和则必利，盖义公天下之利，本有自然之和也。物者义之体，义者物之用，乃处物得宜之谓也。物虽万有不齐，然各有自然之定理，故能处物得宜而不相妨害，则上下尊卑之间，自恩义洽浃，无所乖戾，而义无不合矣。固者，坚固不摇，乃贞之恒久正大也。盖事有未正，必欲其正，事之既正，必守其正，此贞固二字之义也。贞而又固，故足以干事。干者事之干也，赖之为依据也。亦犹木有干而枝叶可依也。凡事或不能贞，或贞而不固，皆知不能及之，是以不能择而守之，故非至灵至明，是非确然不可移易者，决不能贞固，所以贞固为智之事。</p><h3 id="君子行此四德者-故曰乾元亨利贞。" tabindex="-1">君子行此四德者，故曰乾元亨利贞。 <a class="header-anchor" href="#君子行此四德者-故曰乾元亨利贞。" aria-label="Permalink to “君子行此四德者，故曰乾元亨利贞。”">​</a></h3><p>故曰，古语也。行此四德，即体仁嘉会利物贞固也。行此四德，则与乾元合其德矣，故曰乾元亨利贞，所以明君子即干也。</p><h3 id="初九曰-潜龙勿用-何谓也-子曰-龙-德而隐者也-不易乎世-不成乎名-遁世无闷-不见是而无闷-乐则行之-忧则违之-确乎其不可拔-潜龙也。" tabindex="-1">初九曰“潜龙勿用”，何谓也?子曰：龙，德而隐者也，不易乎世，不成乎名，遁世无闷，不见是而无闷，乐则行之，忧则违之，确乎其不可拔，潜龙也。 <a class="header-anchor" href="#初九曰-潜龙勿用-何谓也-子曰-龙-德而隐者也-不易乎世-不成乎名-遁世无闷-不见是而无闷-乐则行之-忧则违之-确乎其不可拔-潜龙也。" aria-label="Permalink to “初九曰“潜龙勿用”，何谓也?子曰：龙，德而隐者也，不易乎世，不成乎名，遁世无闷，不见是而无闷，乐则行之，忧则违之，确乎其不可拔，潜龙也。”">​</a></h3><p>初九曰潜龙勿用何谓也，此文章问答之祖也。后儒如屈原《渔父》见而问之、扬雄《法言》用或问，皆祖于此。圣人神明不测，故曰龙德隐，在下位也。易移也，不易乎世者，邪世不能乱，不为世所移而能拔于流俗风靡之中也。不成乎名者，务实不务名，有一才一艺之长，不求知于世，以成就我之名也。遁世无闷者，不见用于世而不闷也。不见是而无闷者，不见信于人而不闷也。事有快乐于心者，则奋然而行之，忘食忘忧之类是也。事有拂逆于心者，则顺适而背之，伐木绝粮之类是也。违者背也，言不以拂逆为事，皆置之度外而背之背后不见之意。如困于陈蔡，犹援琴而歌是也，盖不易乎世，而不为世所用，不成乎名，而不为世所取，则必遁世而不见信于人矣，而圣人皆无闷焉。是以日用之间，莫非此道之游衍。凡一切祸福毁誉，如太虚浮云，皆处之泰然，无意必固我之私，此所以乐则行，忧则违，忧乐皆无与于己，而安于所遇矣，非龙德何以有此?拔者擢也，举而用之也。不可拔，即勿用也，言坚确不可举用也。盖不易乎世六句，龙德也，确乎其不可拔而隐也。龙德而隐，此所以为潜龙也。乾卦六爻，文言皆以圣人明之，有隐显，无浅深。</p><h3 id="九二曰-见龙在田-利见大人-何谓也-子曰-龙德而正中者也-庸言之信-庸行之谨-闲邪存其诚-善世而不伐-德博而化。易曰-见龙在田-利见大人-君德也。" tabindex="-1">九二曰“见龙在田，利见大人”，何谓也?子曰：龙德而正中者也，庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。易曰“见龙在田，利见大人”，君德也。 <a class="header-anchor" href="#九二曰-见龙在田-利见大人-何谓也-子曰-龙德而正中者也-庸言之信-庸行之谨-闲邪存其诚-善世而不伐-德博而化。易曰-见龙在田-利见大人-君德也。" aria-label="Permalink to “九二曰“见龙在田，利见大人”，何谓也?子曰：龙德而正中者也，庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。易曰“见龙在田，利见大人”，君德也。”">​</a></h3><p>正中者，以下卦言初居下，三居上，二正当其中也。庸常也。邪自外入，故防闲之。诚自我有，故存主之。庸言必信者，无一言之不信也。庸行必谨者，无一行之不谨也。庸言庸行，亦信亦谨，宜无事于闲邪矣，而犹闲邪存诚。闲邪存其诚者，无一念之不诚也，念念皆诚，则发之言行愈信谨矣。如此则其德已盛，善盖一世矣。然心不自满，不自以为善，其主谨闲邪存诚犹夫其初也，皆纯一不已之功也。德博而化者，言行为人所取法也。言君德者，明其非君位也。</p><h3 id="九三曰-君子终日乾乾-夕惕若-厉无咎-何谓也-子曰-君子进德修业-忠信所以进德也-修辞立其诚所以居业也。知至至之-可与几也。知终终之-可与存义也。是故居上位而不骄-在下位而不忧-故乾乾因其时而惕-虽危无咎矣。" tabindex="-1">九三曰“君子终日乾乾，夕惕若，厉无咎”，何谓也?子曰：君子进德修业，忠信所以进德也，修辞立其诚所以居业也。知至至之，可与几也。知终终之，可与存义也。是故居上位而不骄，在下位而不忧，故乾乾因其时而惕，虽危无咎矣。 <a class="header-anchor" href="#九三曰-君子终日乾乾-夕惕若-厉无咎-何谓也-子曰-君子进德修业-忠信所以进德也-修辞立其诚所以居业也。知至至之-可与几也。知终终之-可与存义也。是故居上位而不骄-在下位而不忧-故乾乾因其时而惕-虽危无咎矣。" aria-label="Permalink to “九三曰“君子终日乾乾，夕惕若，厉无咎”，何谓也?子曰：君子进德修业，忠信所以进德也，修辞立其诚所以居业也。知至至之，可与几也。知终终之，可与存义也。是故居上位而不骄，在下位而不忧，故乾乾因其时而惕，虽危无咎矣。”">​</a></h3><p>几与义非二事。几者心之初动也，当欲忠信修辞立诚之初，心之萌动，必有其几。几微之际，乃义之发源处也。义者事之得宜也，方忠信修辞立诚之后，事之成就必见乎义，允蹈之宜，乃几之结果处也。与者许也，可与几者，几有善恶，许其几之如此，方不差也。存者守而不失也。三爻变，则中爻为巽，有进象，又为兑，有言辞象，又为离明，有知象。以三画卦论，三居上，居上位象。以六画卦论，三居下，在下位象。</p><p>君子终日乾乾夕惕若者，非无事而徒动也，勤于进德修业也。然以何者为德业，德业何以用功?盖德者，即贞实之理，诚之涵于心者也。人不忠信，则此心不实，安能进德，惟忠信而内无一念之不实，则心不外驰，而有以复还其贞实之理，所进之德，自日新而不穷矣。故所以进德业者，即贞实之事。诚之发于事者也，言不顾行，则事皆虚伪，安能居业?惟修省其辞以立诚，而外无一言之不实，则言行相顾有以允蹈其贞实之事，所居之业，自居安而不迁矣，故所以居业。夫德业之进修，固在于忠信修辞立诚矣。然其入门用功，当何如哉?亦知行并进而已。盖其始也，知德业之所当至，此心必有其几，当几之初，下此实心，而必欲其至，知至即至之，则念念不差，意可得而诚矣。几动不差，此其所以可与几也。其终也，知德业之所当终，此事必有其义，见义之时，行此实事，而必欲其终，知终即终之，则事事皆当身可得而修矣。义守不失，此其所以可与存义也，如此用功，则反身而诚，德崇而业广矣。又焉往而不宜哉!故以之居上，高而不骄。以之在下，卑而不戚，虽危无咎矣。此君子所以终日乾乾也。</p><h3 id="九四曰-或跃在渊-无咎-何谓也-子曰-上下无常-非为邪也-进退无恒-非离群也。君子进德修业-欲及时也-故无咎。" tabindex="-1">九四曰“或跃在渊，无咎”，何谓也?子曰：上下无常，非为邪也;进退无恒，非离群也。君子进德修业，欲及时也，故无咎。 <a class="header-anchor" href="#九四曰-或跃在渊-无咎-何谓也-子曰-上下无常-非为邪也-进退无恒-非离群也。君子进德修业-欲及时也-故无咎。" aria-label="Permalink to “九四曰“或跃在渊，无咎”，何谓也?子曰：上下无常，非为邪也;进退无恒，非离群也。君子进德修业，欲及时也，故无咎。”">​</a></h3><p>在田者，安于下，在天者，安于上，有常者也。进而为飞，退而为见，有恒者也。恒即常字，九四之位，逼九五矣，以上进为常，则觊觎而心邪。今或跃或处，上下无常，而非为邪也。以下退为常，则离群而德孤。今去就从宜，进退无常，而非离群也。惟及时以进修，而不干时以行险，此其所以无咎也。上进释跃字义，下退释渊字义。无常无恒释或字义。非为邪，非离群，释无咎义。</p><h3 id="九五曰-飞龙在天-利见大人-何谓也-子曰-同声相应-同气相求。水流湿-火就燥。云从龙-风从虎-圣人作而万物睹。本乎天者亲上-本乎地者亲下-则各从其类也。" tabindex="-1">九五曰“飞龙在天，利见大人”，何谓也?子曰：同声相应，同气相求。水流湿，火就燥。云从龙，风从虎，圣人作而万物睹。本乎天者亲上，本乎地者亲下，则各从其类也。 <a class="header-anchor" href="#九五曰-飞龙在天-利见大人-何谓也-子曰-同声相应-同气相求。水流湿-火就燥。云从龙-风从虎-圣人作而万物睹。本乎天者亲上-本乎地者亲下-则各从其类也。" aria-label="Permalink to “九五曰“飞龙在天，利见大人”，何谓也?子曰：同声相应，同气相求。水流湿，火就燥。云从龙，风从虎，圣人作而万物睹。本乎天者亲上，本乎地者亲下，则各从其类也。”">​</a></h3><p>同声相应，如鹤鸣而子和，雄鸣而雌应之类是也。同气相求，如日火之精，而取火于日。月水之精，而取水于月之类是也。湿者下地，故水之流趋之。燥者干物，故火之然就之。云水气也，龙兴则云生，故云从龙。风阴气也，虎啸则风烈，故风从虎。然此特一物亲一物也。惟圣人以圣人之德，居天子之位，则三才之主，而万物之天地矣。是以天下万民莫不瞻仰其德，而快睹其光。所谓首出庶物，万国咸宁，而万物皆亲矣。盖不特一物之亲而已也，所以然者，以天地阴阳之理，皆各从其类也。如天在上，轻清者也，凡本乎天，日月星辰，轻清成象者，皆亲之。地在下，重浊者也，凡本乎地，虫兽草木，重浊成形者，皆亲之。盖天属阳，轻清者属阳，故从其阳之类;地属阴，重浊者属阴，故从其阴之类。阳从其阳，故君子与君子同类而相亲，阴从其阴，故小人与小人同类而相亲。然则以九五之德位，岂不利见同类之大人，所以利见者以此。</p><h3 id="上九曰-亢龙有悔-何谓也-子曰-贵而无位-高而无民-贤人在下而无辅-是以动而有悔也。" tabindex="-1">上九曰“亢龙有悔”，何谓也?子曰：贵而无位，高而无民，贤人在下而无辅，是以动而有悔也。 <a class="header-anchor" href="#上九曰-亢龙有悔-何谓也-子曰-贵而无位-高而无民-贤人在下而无辅-是以动而有悔也。" aria-label="Permalink to “上九曰“亢龙有悔”，何谓也?子曰：贵而无位，高而无民，贤人在下而无辅，是以动而有悔也。”">​</a></h3><p>六，龙之首，故曰高贵。非君非臣，故曰无位。纯阳无阴，故曰无民。五居九五之位，又有快睹之民。九四以下，龙德之贤，皆相从九五以辅相矣。是以上九非不贵也，贵宜乎有位，而无位;非不高也，高宜乎有民，而无民;非不有贤人也，贤人宜辅而莫为之辅。无位无民无辅，则离群孤立，如是而动，其谁我与?有悔必矣。此第二节申象传之意。</p><h3 id="潜龙勿用-下也。" tabindex="-1">潜龙勿用，下也。 <a class="header-anchor" href="#潜龙勿用-下也。" aria-label="Permalink to “潜龙勿用，下也。”">​</a></h3><p>言在下位也。</p><h3 id="见龙在田-时舍也。" tabindex="-1">见龙在田，时舍也。 <a class="header-anchor" href="#见龙在田-时舍也。" aria-label="Permalink to “见龙在田，时舍也。”">​</a></h3><p>舍，止息也，出潜离隐，而止息于田也。</p><h3 id="终日乾乾-行事也。" tabindex="-1">终日乾乾，行事也。 <a class="header-anchor" href="#终日乾乾-行事也。" aria-label="Permalink to “终日乾乾，行事也。”">​</a></h3><p>非空忧惕，乃行所当行之事也，即进德修业也。</p><h3 id="或跃在渊-自试也。" tabindex="-1">或跃在渊，自试也。 <a class="header-anchor" href="#或跃在渊-自试也。" aria-label="Permalink to “或跃在渊，自试也。”">​</a></h3><p>试可乃已之试，非试其德，试其时也，非自试则必妄动矣。</p><h3 id="飞龙在天-上治也。" tabindex="-1">飞龙在天，上治也。 <a class="header-anchor" href="#飞龙在天-上治也。" aria-label="Permalink to “飞龙在天，上治也。”">​</a></h3><p>居上以治下。</p><h3 id="亢龙有悔-穷之灾也。" tabindex="-1">亢龙有悔，穷之灾也。 <a class="header-anchor" href="#亢龙有悔-穷之灾也。" aria-label="Permalink to “亢龙有悔，穷之灾也。”">​</a></h3><p>穷者亢，灾者悔。</p><h3 id="乾元用九-天下治也。" tabindex="-1">乾元用九，天下治也。 <a class="header-anchor" href="#乾元用九-天下治也。" aria-label="Permalink to “乾元用九，天下治也。”">​</a></h3><p>用九见群龙无首吉，此周公教占者当如此也。孔子此则专以人君言元者，仁也，即体仁以长人也。言人君体干之元，用干之九至诚恻怛之爱，常流行于刚果严肃之中，则张弛有则，宽猛得宜，不刚不柔，敷政优优，而天下治矣。此第三节再申前意。</p><h3 id="潜龙勿用-阳气潜藏。" tabindex="-1">潜龙勿用，阳气潜藏。 <a class="header-anchor" href="#潜龙勿用-阳气潜藏。" aria-label="Permalink to “潜龙勿用，阳气潜藏。”">​</a></h3><p>阳在下也，以爻言;潜龙勿用，下也，以位言。此则以气言，言阳气潜藏，正阴气极盛之时，天地闭，贤人隐，所以勿用。此以下，又圣人歌咏乾道之意。观其句，皆四字，有音韵，可知矣。</p><h3 id="见龙在田-天下文明。" tabindex="-1">见龙在田，天下文明。 <a class="header-anchor" href="#见龙在田-天下文明。" aria-label="Permalink to “见龙在田，天下文明。”">​</a></h3><p>虽在下位，然天下已被其德化，而成文明之俗矣，因此爻变离，故以文明言之。</p><h3 id="终日乾乾-与时偕行。" tabindex="-1">终日乾乾，与时偕行。 <a class="header-anchor" href="#终日乾乾-与时偕行。" aria-label="Permalink to “终日乾乾，与时偕行。”">​</a></h3><p>天之健，终日不息，九三之进修，亦与之偕行而不息，故曰与时偕行。</p><h3 id="或跃在渊-乾道乃革。" tabindex="-1">或跃在渊，乾道乃革。 <a class="header-anchor" href="#或跃在渊-乾道乃革。" aria-label="Permalink to “或跃在渊，乾道乃革。”">​</a></h3><p>革者，离下内卦之位，升上外卦之位也。</p><h3 id="飞龙在天-乃位乎天德。" tabindex="-1">飞龙在天，乃位乎天德。 <a class="header-anchor" href="#飞龙在天-乃位乎天德。" aria-label="Permalink to “飞龙在天，乃位乎天德。”">​</a></h3><p>天德即天位，有是天德，而居是天位，故曰乃位乎天德。若无德以居之者，可谓之天位，不可谓之天德之位也，惟圣人在天子之位，斯可言乃为乎天德也。</p><h3 id="亢龙有悔-与时偕极。" tabindex="-1">亢龙有悔，与时偕极。 <a class="header-anchor" href="#亢龙有悔-与时偕极。" aria-label="Permalink to “亢龙有悔，与时偕极。”">​</a></h3><p>当亢极，而我不能变通，亦与时运俱极，所以有悔。</p><h3 id="乾元用九-乃见天则。" tabindex="-1">乾元用九，乃见天则。 <a class="header-anchor" href="#乾元用九-乃见天则。" aria-label="Permalink to “乾元用九，乃见天则。”">​</a></h3><p>龙之为物，春分而升于天，秋分而蛰于渊。曰亢龙者，言秋分亢举于上，而不能蛰也。以春夏秋冬配四德，元者春也，利者秋也，亢龙在此，秋之时矣。天之为天，不过生杀而已。春既生矣，至秋又杀;秋既杀矣，至春又生，此天道一定，自然之法则也。今为人君者，体春生之元，而用之于秋杀之亢，则是阴惨之后继之以阳舒，肃杀之馀继之以生育，一张一弛，一刚一柔，不惟天下可治，而天道之法，则亦于此而见矣，故曰乃见天则。此四节又申前意。</p><h3 id="乾元者-始而亨者也。利贞者-性情也。乾始能以美利利天下-不言所利-大矣哉。" tabindex="-1">乾元者，始而亨者也。利贞者，性情也。乾始能以美利利天下，不言所利，大矣哉。 <a class="header-anchor" href="#乾元者-始而亨者也。利贞者-性情也。乾始能以美利利天下-不言所利-大矣哉。" aria-label="Permalink to “乾元者，始而亨者也。利贞者，性情也。乾始能以美利利天下，不言所利，大矣哉。”">​</a></h3><p>始而亨者，言物方资始之时，已亨通矣。盖出乎震，则必齐乎巽，见乎离，势之必然也。若不亨通，则生意必息，品物不能流形矣。是始者元也，亨之者亦元也。性者百物具足之理，情者百物出入之机，春作夏长，百物皆有性情，非必利贞而后见。但此时生意未足，实理未完，百物尚共同一性情，至秋冬则百谷草木，各正性命，保合太和，一物各具一性情，是收敛归藏，乃见性情之的确。故利贞者，即乾元之性情也，则利贞之未始不为元也。乾始者，即乾元者始而亨之始也。以美利利天下者，元能始物，能始庶物生成，无物不嘉美，亦无物不利赖也。不言所利者，自成其形，自成其性，泯机缄于不露，莫知其所以然也。大哉，赞乾元也。</p><p>孔子于文言，既分元亨利贞为四德矣，此又合而为一也。言干之元者，始而即亨者也;利贞者，则元之性情耳。然何以知其元始即亨，利贞即元之性情也。惟自其乾元之所能者，则可见矣。盖百物生于春，非亨利贞之所能也，惟元为生物之始。以美利利天下者，则乾元之能也。夫以美利利天下，其所能之德业，亦盛大矣。使造化可以言焉，则曰此某之美利也，庶乎可以各归功于四德矣。今不言所利，人不得而测之，既不可得而测，则是四德浑然一理，不可分而言也。元本为四德之长，故谓亨，乃元之始亨可也。谓利贞，乃元之性情可也。所以谓乾元始而亨，利贞性情者，以此乾元之道，不其大哉。四德本一理，孔子赞易，或分而言之以尽其用，或合而言之以著其体，其实一理而已，所以可分可合也。</p><h3 id="大哉干乎-刚健中正-纯粹精也。六爻发挥-旁通情也。时乘六龙-以御天也。云行雨施-天下平也。" tabindex="-1">大哉干乎，刚健中正，纯粹精也。六爻发挥，旁通情也。时乘六龙，以御天也。云行雨施，天下平也。 <a class="header-anchor" href="#大哉干乎-刚健中正-纯粹精也。六爻发挥-旁通情也。时乘六龙-以御天也。云行雨施-天下平也。" aria-label="Permalink to “大哉干乎，刚健中正，纯粹精也。六爻发挥，旁通情也。时乘六龙，以御天也。云行雨施，天下平也。”">​</a></h3><p>刚以体言，健以性言，中者无过不及也，正者不偏也，此四者干之德也。纯者纯阳而不杂以阴也，粹者不杂而良美也，精者不杂之极至也，总言乾德刚健中正之至极。所谓纯粹精者，非出于刚健中正之外也，但乾德之妙，非一言所能尽，故于刚健中正之外，复以纯粹精赞之。情者事物至赜至动之情也，发挥者每一画有一爻辞以发挥之也，旁通者曲尽也，如初之潜以至上之亢，凡事有万殊，物有万类，时有万变，皆该括曲尽其情而无遗也。前品物流形，乃干之云行雨施，此言云行雨施，乃圣人乘六龙而御天之功德泽流行敷布，所以天下平也。</p><p>言乾道刚健中正，纯粹以精。乾道固大矣，惟圣人立六爻以通乎干之情，乘六龙以行乎干之道。云行雨施，以沛乎干之泽，以至天下太平，则乾道之大不在干而在圣人矣。此第五节复申首章之意。</p><h3 id="君子以成德为行-日可见之行也。潜之为言也-隐而未见-行而未成-是以君子弗用也。" tabindex="-1">君子以成德为行，日可见之行也。潜之为言也，隐而未见，行而未成，是以君子弗用也。 <a class="header-anchor" href="#君子以成德为行-日可见之行也。潜之为言也-隐而未见-行而未成-是以君子弗用也。" aria-label="Permalink to “君子以成德为行，日可见之行也。潜之为言也，隐而未见，行而未成，是以君子弗用也。”">​</a></h3><p>德者行之本，行者德之用，盖有有其德而不见诸行者，未有有其行而不本诸德者，故曰君子以成德为行。成德者，已成之德也。日可见者，犹言指日可待之意。此二句泛论其理也。潜者周公爻辞也。未见者，天地闭，贤人隐，厄于潜之机会而未见也。未成者，因其厄而事业未成就也，如伊尹耕于有莘之野是也。</p><p>君子以已成之德，举而措之于行，则其事业之所就，指日可见矣。初九其德已成，则日可见之行也，而占者乃曰勿用，何也?盖圣人出世，必有德有时。人之所能者德，所不能者时。今初九虽德已成，然时当乎潜也。潜之为言也，隐而未见也。惟其隐而未见，故行而未成，时位厄之也。是以占者之君子，亦当如之而勿用也。</p><h3 id="君子学以聚之-问以辨之-宽以居之-仁以行之。易曰-见龙在田-利见大人-君德也。" tabindex="-1">君子学以聚之，问以辨之，宽以居之，仁以行之。易曰“见龙在田，利见大人”，君德也。 <a class="header-anchor" href="#君子学以聚之-问以辨之-宽以居之-仁以行之。易曰-见龙在田-利见大人-君德也。" aria-label="Permalink to “君子学以聚之，问以辨之，宽以居之，仁以行之。易曰“见龙在田，利见大人”，君德也。”">​</a></h3><p>之者正中之理也。龙德正中，虽以爻言，然圣人之德，不过此至正大中而已。盖乾道刚健中正，民受天地之中以生，惟中庸不可能，苟非学聚问辨，有此致知功夫，宽居仁行，有此力行功，夫安能体此龙德之正中乎。聚者多闻多见以我会聚，此正中之理也。辨者讲学也，亲师取友，辨其理之精粗本末，得失是非，择其正中之善者而从之，即讲学以耨之也。宽者优游厌饫，勿忘勿助，俾所聚所辨，此理之畜于我者，融会贯通，渣滓浑化，无强探力索，凌节欲速之患也。盖宽字以久远言，有从容不迫之意，非专指包含也。居者守也据也，仁以行之者，无适而莫非天理正中之公，而无一毫意必固我之私也。盖辨者辨其所聚，居者居其所辨，行者行其所居，故必宽以居之，而后方可仁以行之。若学聚问辨之馀，涵养未久，粗心浮气，而骤欲见之于实践，则居之不安，资之不深，安能左右逢原，而大公以顺应哉。此为学一定之序也，有是四者，宜乎正中之德，博而化矣。曰君德者，即前九二之君德也。</p><h3 id="九三重刚而不中-上不在天-下不在田-故乾乾。因其时而惕-虽危无咎矣。" tabindex="-1">九三重刚而不中，上不在天，下不在田，故乾乾。因其时而惕，虽危无咎矣。 <a class="header-anchor" href="#九三重刚而不中-上不在天-下不在田-故乾乾。因其时而惕-虽危无咎矣。" aria-label="Permalink to “九三重刚而不中，上不在天，下不在田，故乾乾。因其时而惕，虽危无咎矣。”">​</a></h3><p>三居下卦之上，四居上卦之下，交接处，以刚居刚，故曰重刚，非阳爻居阳位也。所以九四居阴位者，亦曰重刚。位非二五，故曰不中。即下文上不在天，下不在田也。九三以时言，九四以位言，故曰乾乾，因其时。</p><p>九三重刚不中，上不在天，下不在田，宜有咎矣，而乃无咎，何哉?盖既重刚又不中，刚之极矣。以时论之，盖危惧之时也。故九三因其时而兢惕不已，则德日进，业日修，所以虽处危地，亦无咎矣。</p><h3 id="九四重刚而不中-上不在天-下不在田-中不在人-故或之。或之者-疑之也-故无咎。" tabindex="-1">九四重刚而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故无咎。 <a class="header-anchor" href="#九四重刚而不中-上不在天-下不在田-中不在人-故或之。或之者-疑之也-故无咎。" aria-label="Permalink to “九四重刚而不中，上不在天，下不在田，中不在人，故或之。或之者，疑之也，故无咎。”">​</a></h3><p>在人谓三也。四三虽皆人位，然四则居人之上，而近君矣。非三之不近君，故曰不在人。重刚不中之中，二五之中也。中不在人之中，六爻中间之中也。</p><p>九四重刚不中，上不在天，下不在田，中不在人，宜有咎矣，而乃无咎，何哉?盖九四之位不在天，不在田，虽与九三同，而人位则不如九三之居下卦也，所居之位独近九五，盖或之之位也，故或之。或之者疑之也，惟其疑，必审时而进矣，所以无咎也。</p><h3 id="夫大人者-与天地合其德-与日月合其明-与四时合其序-与鬼神合其吉凶-先天而天弗违-后天而奉天时-天且弗违-而况于人乎-况于鬼神乎。-夫音扶" tabindex="-1">夫大人者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶，先天而天弗违，后天而奉天时，天且弗违，而况于人乎，况于鬼神乎。(夫音扶) <a class="header-anchor" href="#夫大人者-与天地合其德-与日月合其明-与四时合其序-与鬼神合其吉凶-先天而天弗违-后天而奉天时-天且弗违-而况于人乎-况于鬼神乎。-夫音扶" aria-label="Permalink to “夫大人者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶，先天而天弗违，后天而奉天时，天且弗违，而况于人乎，况于鬼神乎。(夫音扶)”">​</a></h3><p>合德以下，总言大人所具之德，皆天理之公，而无一毫人欲之私。若少有一毫人欲之私，即不合矣。天地者造化之主，日月者造化之精，四时者造化之功，鬼神者造化之灵，覆哉无私之谓德，照临无私之谓明，生息无私之谓序，祸福无私之谓吉凶。合序者如赏以春夏，罚以秋冬之类也。合吉凶者，福善祸淫也。先天不违如礼，虽先王所未有，以义起之，凡制耒耜、作书契之类。虽天下之所未为，而吾意之所为，默与道契，天亦不违乎我，是天合大人也。奉天时者，奉天理也。后天奉天时谓如天叙有典，而我惇之，天秩有礼，而我庸之类，虽天之所已为，我知理之如是，奉而行之，而我亦不能违乎天，是大人合天也。盖以理为主，天即我，我即天，故无后先彼此之可言矣。且不违于大人，而况于人。乃得天地之理以生鬼神，不过天地之功用，虽欲违乎大人，自不能违乎天矣。干之九五，以刚健中正之德，与此大人相合，所以宜利见之，以其同德相应也。</p><h3 id="亢之为言也-知进而不知退-知存而不知亡-知得而不知丧-其惟圣人乎。知进退存亡而不失其正者-其唯圣人乎。" tabindex="-1">亢之为言也，知进而不知退，知存而不知亡，知得而不知丧，其惟圣人乎。知进退存亡而不失其正者，其唯圣人乎。 <a class="header-anchor" href="#亢之为言也-知进而不知退-知存而不知亡-知得而不知丧-其惟圣人乎。知进退存亡而不失其正者-其唯圣人乎。" aria-label="Permalink to “亢之为言也，知进而不知退，知存而不知亡，知得而不知丧，其惟圣人乎。知进退存亡而不失其正者，其唯圣人乎。”">​</a></h3><p>进退者身，存亡者位，得丧者物。消长之理，知之既明，不失其正，处之又当，故惟圣人能之。再言其唯圣人，始若设问，而卒自应之，见非圣人不能也。初九隐而未见二句，释一潜字。而言君子者再，盖必君子而后能安于潜也。上九亢之为言三句，释一亢字。而言圣人者再，盖必圣人而后能不至于亢也。此第六节复申前数节未尽之意。</p>',120)])])}const m=e(l,[["render",p]]);export{b as __pageData,m as default};
